<?php require 'config/config.php';auth();$s=db()->prepare("SELECT a.*,b.move_in_date,b.months,b.advance_amount,r.room_number,r.rent,p.title,p.address,p.city,o.name owner,t.name tenant,t.email tenant_email,t.phone tenant_phone FROM rental_agreements a JOIN bookings b ON b.id=a.booking_id JOIN rooms r ON r.id=b.room_id JOIN properties p ON p.id=r.property_id JOIN users o ON o.id=p.owner_id JOIN users t ON t.id=b.user_id WHERE a.id=? AND b.user_id=?");$s->execute([(int)$_GET['id'],user()['id']]);$a=$s->fetch();if(!$a)exit('Agreement not found');function pe($s){return str_replace(['\\','(',')',"\r","\n"],['\\\\','\\(','\\)',' ',' '],(string)$s);}function pdf($ls){$o=[];$o[]='<< /Type /Catalog /Pages 2 0 R >>';$o[]='<< /Type /Pages /Kids [3 0 R] /Count 1 >>';$o[]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>';$o[]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';$st="BT\n/F1 16 Tf\n45 800 Td\n(SmartStay - Rental Agreement) Tj\n/F1 10 Tf\n0 -25 Td\n";foreach($ls as $l){$st.='('.pe($l).') Tj' . "\n0 -16 Td\n";}$st.='ET';$o[]='<< /Length '.strlen($st).' >>\nstream\n'.$st.'\nendstream';$p="%PDF-1.4\n";$off=[0];foreach($o as $i=>$x){$off[$i+1]=strlen($p);$p.=($i+1).' 0 obj\n'.$x.'\nendobj\n';}$x=strlen($p);$p.='xref\n0 '.(count($o)+1).'\n0000000000 65535 f \n';for($i=1;$i<=count($o);$i++)$p.=sprintf('%010d 00000 n \n',$off[$i]);return $p.'trailer\n<< /Size '.(count($o)+1).' /Root 1 0 R >>\nstartxref\n'.$x.'\n%%EOF';}$ls=['Agreement No: '.$a['agreement_no'],'Generated: '.date('d M Y H:i'),'','TENANT: '.$a['tenant'],'Email: '.$a['tenant_email'],'Phone: '.$a['tenant_phone'],'OWNER: '.$a['owner'],'','PROPERTY: '.$a['title'],'Address: '.$a['address'].', '.$a['city'],'Room: '.$a['room_number'],'','Move-in: '.date('d M Y',strtotime($a['move_in_date'])),'Period: '.$a['months'].' month(s)','Monthly rent: '.money($a['rent']),'Advance paid: '.money($a['advance_amount']),'Payment reference: '.$a['payment_transaction_id'],'','TERMS','1. Residential use only.','2. Tenant agrees to pay rent on time.','3. Tenant will maintain the room.','4. Changes should be recorded by both parties.','5. Project-generated digital agreement.','','Tenant: '.$a['tenant'],'Owner: '.$a['owner'],'STATUS: PAID / CONFIRMED'];header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="SmartStay-'.$a['agreement_no'].'.pdf"');echo pdf($ls);
